// Conversion offer logic: when paidEvents is zero, inject a discount offer into checkout
const axios = require('axios');

async function injectConversionOffer(checkoutSession) {
  // If no paid events yet, add a 20% discount coupon
  if (checkoutSession.totalAmount > 0 && !checkoutSession.discountApplied) {
    checkoutSession.discountPercent = 20;
    checkoutSession.discountApplied = true;
    checkoutSession.finalAmount = checkoutSession.totalAmount * 0.8;
    // Log the offer
    console.log(`Conversion offer injected: 20%% off for session ${checkoutSession.id}`);
  }
  return checkoutSession;
}

async function trackPaidEvent(event) {
  // Increment paidEvents counter in revenue stats
  try {
    await axios.post('http://localhost:4000/api/revenue/track-paid', { event });
  } catch (err) {
    console.error('Failed to track paid event:', err.message);
  }
}

module.exports = { injectConversionOffer, trackPaidEvent };
